// Normalizes one intake submission. Keys on QUESTION TEXT, never column index --
// Google Forms appends new questions to the far right of the sheet and leaves
// deleted questions' columns in place, so position is not stable.

const Q = {
  SPANISH: {
    email: 'Correo electrónico',
    name:  'Nombre y apellido completo',
    phone: 'Teléfono celular (con código de país)',
    hours: '¿Cuántas horas por semana tienes disponibles para entrenar?',
    week:  'Cuéntame cómo sería tu semana ideal de entrenamiento',
    sport: '¿Cuál es la disciplina principal que entrenarás con nosotros?',
  },
  ENGLISH: {
    email: 'Email address',
    name:  'Full name',
    phone: 'Mobile Phone (with country code)',
    hours: 'How many hours per week do you have available to train?',
    week:  'Tell me what your ideal training week would look like',
    sport: 'What is the primary discipline or the one you want to train for with us?',
  },
};

// Tolerates trailing spaces and case drift in question text -- "Disponibilidad
// semanal [Sábado ]" in the live form already has one.
function pick(answers, label) {
  if (label && answers[label] !== undefined) return answers[label];
  const want = String(label || '').trim().toLowerCase();
  for (const k of Object.keys(answers)) {
    if (k.trim().toLowerCase() === want) return answers[k];
  }
  return '';
}

return $input.all().map(item => {
  const b = item.json.body || item.json;
  const answers = b.answers || {};
  const lang = Q[b.form_language] ? b.form_language : 'SPANISH';
  const q = Q[lang];

  // Fuzzy fallback for the sport question: its wording differs slightly between
  // the two forms and is the most likely to be reworded.
  let sport = pick(answers, q.sport);
  if (!sport) {
    const k = Object.keys(answers).find(k =>
      /disciplina principal|primary discipline/i.test(k));
    if (k) sport = answers[k];
  }

  const email = String(pick(answers, q.email) || '').trim();

  return { json: {
    ok: Boolean(email),
    form_language: lang,
    email,
    full_name: pick(answers, q.name),
    phone: pick(answers, q.phone),
    sport,
    hours_available: pick(answers, q.hours),
    ideal_week: pick(answers, q.week),
    answer_count: Object.keys(answers).length,
    raw: JSON.stringify({ form_language: lang, sheet_name: b.sheet_name || '',
                          submitted_at: b.submitted_at || '', answers }),
  }};
});

// Builds the briefing prompt. Grounded in methodology.md -- the rules below are
// condensed from sections 2, 3 and 5, not invented. If methodology.md changes,
// this prompt is the thing to update.

const MODEL = 'gemini-3.1-pro-preview';  // same model the content engine's writer uses

const norm = $('Normalize Intake').item.json;
const raw  = JSON.parse(norm.raw || '{}');
const answers = raw.answers || {};

// Age matters: methodology.md section 5 gives athletes 50+ a 2+1 block structure
// and shortened ATL/CTL constants, so the briefing should raise it rather than
// leave Ivan to spot a birth year.
function ageFrom(s) {
  const m = String(s || '').match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (!m) return null;
  const y = parseInt(m[3], 10);
  const age = new Date().getFullYear() - y;
  return (age > 8 && age < 100) ? age : null;
}
const dob = answers['Fecha de nacimiento'] || answers['Date of Birth'] || '';
const age = ageFrom(dob);

const system = `Sos el asistente de Ivan Koch, entrenador de triatlon y running (Triaperformance).
Tu tarea NO es entrenar. Es prepararle un briefing para que EL planifique, a partir
del formulario de onboarding que acaba de completar un atleta nuevo.

REGLAS DURAS
- No inventes NADA. Si el atleta no dijo algo, escribi exactamente "no lo dijo".
  Es mas util un hueco senalado que un dato inventado.
- No des consejo medico. Si menciona lesion, dolor o condicion medica, listalo como
  dato y agrega "derivar a medico" -- nunca diagnostiques ni sugieras tratamiento.
- No armes el plan de entrenamiento. Ivan lo hace.
- Escribi en espanol rioplatense neutro, directo, sin relleno y sin emojis.
- Numeros antes que adjetivos.

CONTEXTO DE METODOLOGIA (para las secciones 5 y 6)
Tests iniciales segun deporte y equipamiento:
- Running: 30' a maximo esfuerzo. Umbral = pace promedio de los 30'; LTHR = FC media de los ultimos 20'.
- Ciclismo indoor: test rampa (mejor para principiantes).
- Ciclismo outdoor con potenciometro, subida larga: 1x20', FTP = 95% del promedio.
- Ciclismo outdoor con potenciometro, subida corta: 2x8', FTP = 90% del promedio de ambos.
- Ciclismo sin potenciometro: 30' a maxima FC, LTHR = FC media de los ultimos 20'.
- Natacion: 400m + 200m, CSS por calculadora.
Banderas rojas que hay que marcar si aplican:
- Triatleta que no sabe nadar -> no se ensena a nadar; ofrecer run+bike+gym y derivar a tecnico de natacion.
- Corredor sin reloj GPS -> no se puede entrenar asi.
- Ciclista sin potenciometro NI banda de FC -> se entrena a ciegas, evitar.
- Atleta de 50 anos o mas -> bloques 2+1 en vez de 3+1 y constantes ATL/CTL acortadas.

FORMATO DE SALIDA (exactamente estas secciones, en este orden, sin preambulo)

1. RESUMEN
Tres o cuatro lineas: quien es, de donde, que deporte, que busca.

2. OBJETIVO
Carrera A, carrera B, fecha si la dio, y si el plazo es realista para lo que viene entrenando.
Si no hay fecha, decilo.

3. SEMANA PROPUESTA
Tu interpretacion dia por dia de lo que escribio en "semana ideal". El atleta escribe
en prosa y agrupa dias ("martes y jueves", "los demas dias"): desplegalo a los 7 dias.
Marca cada dia con [dicho] si lo dijo explicitamente o [inferido] si lo dedujiste.
Cerra con las horas semanales que declaro disponibles.

4. QUE FALTA PREGUNTAR POR WHATSAPP
La seccion mas importante. Lista concreta y corta de lo que Ivan necesita y el atleta
no dijo: duraciones por sesion, horarios de manana/tarde, que deporte en que dia,
disponibilidad de pileta, dia de descanso, capacidad de dobles. Solo lo que falte de verdad.

5. BANDERAS ROJAS Y CUIDADOS
Lesiones (con "derivar a medico"), banderas rojas de la lista de arriba, edad 50+,
o cualquier incoherencia entre lo que dice que entrena y lo que dice que puede.
Si no hay ninguna, escribi "ninguna".

6. TEST INICIAL SUGERIDO
Que test corresponde segun su deporte y el equipamiento que declaro, y por que ese.
Si el equipamiento no alcanza para el test estandar, deci cual es la alternativa.

7. EQUIPAMIENTO
Reloj, banda de FC, potenciometro, ciclocomputadora, rodillo, gimnasio. Una linea.`;

const user = `Datos del formulario (JSON crudo, tal como los respondio el atleta):

${JSON.stringify(answers, null, 1)}

Edad calculada: ${age === null ? 'no se pudo calcular' : age + ' anos'}
Idioma del formulario: ${norm.form_language}
${raw.language_mismatch ? 'ATENCION: la pestana del sheet y el idioma del formulario no coinciden. Revisar configuracion.' : ''}`;

return [{ json: {
  model: MODEL,
  geminiBody: {
    system_instruction: { parts: [{ text: system }] },
    contents: [{ role: 'user', parts: [{ text: user }] }],
    generationConfig: { temperature: 0.3, maxOutputTokens: 3000 },
  },
}}];

// Gemini returns the text several levels deep and the shape shifts between versions,
// so pull it defensively and fail loudly rather than saving an empty briefing.
const r = $json;
const cand = r?.candidates?.[0];
const parts = cand?.content?.parts || [];
const text = parts.map(p => p?.text || '').join('').trim();

if (!text) {
  throw new Error('Gemini devolvio una respuesta vacia. finishReason=' +
    (cand?.finishReason || 'desconocido') + ' | payload=' + JSON.stringify(r).slice(0, 500));
}

return [{ json: {
  briefing: text,
  briefing_model: $('Build Briefing Prompt').item.json.model,
  briefing_at: new Date().toISOString(),
  intake_id: $('Get Intake Id').item.json.id,
}}];

